function varint(n){n=BigInt(n);const o=[];do{let b=Number(n&127n);n>>=7n;if(n)b|=128;o.push(b)}while(n);return o;}
function encode(fields){const o=[];for(const[n,v]of fields){if(v instanceof Uint8Array){o.push(...varint(n*8+2),...varint(v.length),...v)}else o.push(...varint(n*8),...varint(v))}return Uint8Array.from(o);}
