async function hash(b){return hex(new Uint8Array(await crypto.subtle.digest('SHA-256',b)));}
async function rpc(endpoint,method,params){const url=new URL(endpoint);if(url.protocol!=='https:' && !(url.protocol==='http:'&&['localhost','127.0.0.1'].includes(url.hostname)))throw Error('Use an HTTPS node URL');const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),20000);try{const response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:1,method,params}),signal:controller.signal});if(!response.ok)throw Error('Node returned HTTP '+response.status);const data=await response.json();if(data.error)throw Error(data.error.message||'Chain request failed');if(!data.result)throw Error('No response from node');return data.result;}finally{clearTimeout(timer)}}
