function base58(b){const alphabet='123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';let n=0n;for(const v of b)n=n*256n+BigInt(v);let s='';while(n){s=alphabet[Number(n%58n)]+s;n/=58n}for(const v of b){if(v===0)s='1'+s;else break}return s;}
